        var raw2 = github_get_pr_diff({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            pullRequestID: String(prNumber)
        });
        var obj2 = mcpParse(raw2);
        if (typeof obj2 === 'string' && obj2.length) return obj2;
    } catch (e2) { /* both tiers failed */ }
    return null;
}

