            { event: 'labeled', label: { name: 'po_accept' }, actor: { login: 'human1' }, created_at: '2026-01-02' },
            { event: 'unlabeled', label: { name: 'po_accept' }, actor: { login: 'human1' }, created_at: '2026-01-03' },
