+        prState = guestTransplantModule.prStateFromFindList(list);
+    } catch (ePr) { prState = null; }
+    if (!prState) {
+        var n = guestTransplantModule.parseGuestBranch(branch, cfg.branchPrefix);
+        marker = n ? guestMarker(repoInfo, n) : null;
