+    for (var i = 0; i < names.length; i++) {
+        if (sweep.length >= cap || probed >= budget) break;
+        var entry = guestSweepEntry(repoInfo, cfg, names[i]);
+        probed++;
+        if (guestTransplantModule.gcSteps([entry]).length) sweep.push(entry);
+    }
