function resolveTransplantSha(marker, currentHeadSha) {
    var recorded = marker && marker.head;
    if (recorded && SHA_RE.test(String(recorded))) {
        return {
            sha: String(recorded),
            drifted: !!(currentHeadSha && currentHeadSha !== recorded)
