function guestOpenPrOnBranch(repoInfo, branch) {
    try {
        var res = mcpParse(github_list_prs({
            workspace: repoInfo.owner, repository: repoInfo.repo, state: 'open'
        }));
        var list = Array.isArray(res) ? res : ((res && res.data) || []);
