   if (!allow || !allow.length) return null;
   var found = null;
   for (var i = 0; i < comments.length; i++) {
       if (!_authorAllowed(coments[i], allow)) continue;
       var body = String((comments[i] && comments[i].body) || comments[i] || '');
       var hit = _markerObject(body);
       if (hit) found = hit;
   }
   return found;
}
