// commentAuthorLogin/trustedLogin — kept local): a comment's author
// login, normalized; null when the payload carries none.
function _commentAuthorLogin(item) {
   if (!item) return null;
   var u = item.user || item.author;
   if (!u) return null;
   var login = u.login || u.name;
