+function sequenceHeadSha(seq) {
+    var steps = (seq && seq.steps) || [];
+    for (var i = 0; i < steps.length; i++) {
+        if (steps[i] && steps[i].op === 'merge') return steps[i].headSha || null;
+    }
+    return null;
+}
