+function buildPrLabelsCommand(owner, repo, prNumber) {
+    return 'gh pr view ' + Number(prNumber) + ' --repo "' + owner + '/' + repo +
+        '" --json labels --jq "[.labels[].name] | join(\x27,\x27)"';
