function isMergeConflictError(e) {
    var msg = String((e && e.message) || e || '');
    return msg.indexOf('Merge conflict') !== -1 ||
        msg.toLowerCase().indexOf('conflict') !== -1 ||
        msg.indexOf('409') !== -1;
