function _orphanStep(e) {
    if (e.marker && e.marker.state === 'armed' && e.marker.head) {
        return step('complete_orphan', {
            branch: e.branch,
            sourcePrNumber: e.marker.source,
            headSha: e.marker.head
        });
    }
    return step('delete_ref', { branch: e.branch });
}

