        if (out && out.newPrNumber !== undefined) ctx.newPrNumber = out.newPrNumber;
        if (out && out.mergedSha !== undefined) ctx.mergedSha = out.mergedSha;
        if (out && out.carriedLabels !== undefined) ctx.carriedLabels = out.carriedLabels;
    }
    return ctx;
}

